<div class="flex h-full min-h-0 w-full flex-col gap-4">
<header class="cl-panel shrink-0 p-5"><div class="flex flex-wrap items-center justify-between gap-4"><div><p class="cl-panel-eyebrow">Verification Planning</p><h2 class="text-2xl font-extrabold text-blue-950">Test Management</h2><p class="mt-1 text-sm text-slate-600">Test Cases mit Akzeptanzkriterien verknüpfen.</p></div><div class="flex gap-2"><div class="rounded border bg-slate-50 px-4 py-2 text-center"><b id="tmTcCount" class="block text-xl text-blue-950">0</b><span class="text-[10px] uppercase text-slate-500">Test Cases</span></div><div class="rounded border bg-slate-50 px-4 py-2 text-center"><b id="tmLinkCount" class="block text-xl text-blue-950">0</b><span class="text-[10px] uppercase text-slate-500">Zuordnungen</span></div></div></div></header>
<div class="grid min-h-0 flex-1 grid-cols-1 gap-4 lg:grid-cols-[360px_minmax(0,1fr)]"><aside class="cl-panel flex min-h-0 flex-col overflow-hidden"><div class="border-b p-4"><input id="tmSearch" class="cl-input" type="search" placeholder="Test Case suchen"></div><div id="tmTestCaseList" class="min-h-0 flex-1 overflow-y-auto"></div></aside>
<section class="cl-panel flex min-h-0 flex-col overflow-hidden"><div id="tmEmpty" class="flex h-full items-center justify-center p-8 text-center text-slate-400">Test Case auswählen</div><div id="tmEditor" class="hidden min-h-0 flex-1 flex-col"><div class="border-b p-5"><div class="flex justify-between gap-4"><div><div id="tmSelectedKey" class="font-mono text-sm font-extrabold text-blue-900"></div><h3 id="tmSelectedTitle" class="text-xl font-extrabold"></h3><p id="tmSelectedDescription" class="mt-2 text-sm text-slate-600"></p></div><button id="tmSave" class="cl-button cl-button-primary">Zuordnung speichern</button></div></div><div class="flex gap-3 border-b bg-slate-50 p-4"><input id="tmCriterionSearch" class="cl-input flex-1" type="search" placeholder="Anforderung oder Kriterium suchen"><select id="tmTypeFilter" class="cl-select w-auto"><option value="">Alle Typen</option><option>USR</option><option>SYS</option><option>SEC</option><option>SRS</option><option>HRS</option><option>SWC</option></select></div><div id="tmCriteria" class="min-h-0 flex-1 overflow-y-auto p-4"></div></div></section></div></div>
